import java.io.*;
import java.util.*;

public class C {

    public static void main(String[] args) throws IOException {
        BufferedReader inputReader = new BufferedReader(new InputStreamReader(System.in));
        String inputStr = inputReader.readLine();
        long inputNumber = Long.parseLong(inputStr);
        long answer = calculate(inputNumber);
        System.out.println(answer);
    }

    static long[] ONES = new long[17];
    static {
        ONES[1] = 1;
        for (int i = 2; i < 17; i++) {
            ONES[i] = 10 * ONES[i - 1] + 1;
        }
    }

    static long calculate(long x) {
        return recurse(x, 16);
    }

    static long recurse(long x, int len) {
        x = Math.abs(x);
        if (x % ONES[len] == 0) {
            return (x / ONES[len]) * len;
        }
        long lowerBound = x / ONES[len];
        long upperBound = lowerBound + 1;

        long candidate1 = lowerBound * len + recurse(x - lowerBound * ONES[len], len - 1);
        long candidate2 = upperBound * len + recurse(upperBound * ONES[len] - x, len - 1);
        return Math.min(candidate1, candidate2);
    }
}
